INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (395, 'WINTER_PATTERN_095', 'Mưa nhỏ - Mẫu 95 (Mùa Đông)', 'Mẫu thời tiết #95 Mùa Đông (cơ sở quan trắc 2019-01-16): Mưa nhỏ. Nhiệt độ dao động 10.7°C - 14.7°C, độ ẩm 69.0% - 88.0%, lượng mưa 3.9mm. Mưa ngắt quãng hạt nhỏ.', 10.7, 14.7, 69.0, 88.0, 'Nhiệt đới gió mùa', 'rain_light.svg', 'winter', 4095, TRUE, '2026-10-29 07:30:00');
INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (396, 'WINTER_PATTERN_096', 'Mưa nhỏ - Mẫu 96 (Mùa Đông)', 'Mẫu thời tiết #96 Mùa Đông (cơ sở quan trắc 2018-01-28): Mưa nhỏ. Nhiệt độ dao động 8.6°C - 17.2°C, độ ẩm 79.0% - 96.0%, lượng mưa 10.7mm. Mưa ngắt quãng hạt nhỏ.', 8.6, 17.2, 79.0, 96.0, 'Nhiệt đới gió mùa', 'rain_light.svg', 'winter', 4096, TRUE, '2026-10-29 07:30:00');
INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (397, 'WINTER_PATTERN_097', 'Mưa nhỏ - Mẫu 97 (Mùa Đông)', 'Mẫu thời tiết #97 Mùa Đông (cơ sở quan trắc 2022-01-20): Mưa nhỏ. Nhiệt độ dao động 11.7°C - 20.5°C, độ ẩm 61.0% - 100.0%, lượng mưa 1.9mm. Mưa ngắt quãng hạt nhỏ.', 11.7, 20.5, 61.0, 100.0, 'Nhiệt đới gió mùa', 'rain_light.svg', 'winter', 4097, TRUE, '2026-10-29 07:30:00');
INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (398, 'WINTER_PATTERN_098', 'Mưa nhỏ - Mẫu 98 (Mùa Đông)', 'Mẫu thời tiết #98 Mùa Đông (cơ sở quan trắc 2007-12-22): Mưa nhỏ. Nhiệt độ dao động 16.4°C - 24.6°C, độ ẩm 82.0% - 98.0%, lượng mưa 6.3mm. Mưa ngắt quãng hạt nhỏ.', 16.4, 24.6, 82.0, 98.0, 'Nhiệt đới gió mùa', 'rain_light.svg', 'winter', 4098, TRUE, '2026-10-29 07:30:00');
INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (399, 'WINTER_PATTERN_099', 'Mưa vừa - Mẫu 99 (Mùa Đông)', 'Mẫu thời tiết #99 Mùa Đông (cơ sở quan trắc 2001-12-10): Mưa vừa. Nhiệt độ dao động 15.2°C - 20.6°C, độ ẩm 66.0% - 92.0%, lượng mưa 22.4mm. Mưa đều hạt, lượng mưa trung bình.', 15.2, 20.6, 66.0, 92.0, 'Nhiệt đới gió mùa', 'rain.svg', 'winter', 4099, TRUE, '2026-10-29 07:30:00');
INSERT INTO weather (id, code, name, description, min_temp, max_temp, min_humidity, max_humidity, condition, icon, season, sort_order, is_active, created_at) VALUES (400, 'WINTER_PATTERN_100', 'Mưa to - Mẫu 100 (Mùa Đông)', 'Mẫu thời tiết #100 Mùa Đông (cơ sở quan trắc 2012-12-01): Mưa to. Nhiệt độ dao động 15.0°C - 26.9°C, độ ẩm 82.0% - 99.0%, lượng mưa 32.9mm. Mưa to diện rộng, lưu lượng nước lớn.', 15.0, 26.9, 82.0, 99.0, 'Nhiệt đới gió mùa', 'rain_heavy.svg', 'winter', 4100, TRUE, '2026-10-29 07:30:00');
